ew\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/9/9/\",\"title\":\"TEXT 9\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2618,\"bb\":568215,\"url_path\":\"/en/library/bg/9/8/devanagari/\",\"body_final\":\"प्रकृतिं स्वामवष्टभ्य विसृजामि पुन: पुन: ।
भूतग्राममिमं कृत्स्नमवशं प्रकृतेर्वशात् ॥ ८ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2619,\"bb\":2321,\"url_path\":\"/en/library/bg/9/8/b2321/\",\"body_value\":\"prakṛtiṁ svām avaṣṭabhya
visṛjāmi punaḥ punaḥ
bhūta-grāmam imaṁ kṛtsnam
avaśaṁ prakṛter vaśāt\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2620,\"bb\":2322,\"url_path\":\"/en/library/bg/9/8/b2322/\",\"shadow_value\":\"prakṛtim – the material nature; svām – of My personal Self; avaṣṭabhya – entering into; visṛjāmi – I create; punaḥ punaḥ – again and again; bhūta-grāmam – all the cosmic manifestations; imam – these; kṛtsnam – in total; avaśam – automatically; prakṛteḥ – of the force of nature; vaśāt – under obligation.\",\"word_for_word_value\":[{\"word\":\"prakṛtim\",\"translation\":\"the material nature\"},{\"word\":\"svām\",\"translation\":\"of My personal Self\"},{\"word\":\"avaṣṭabhya\",\"translation\":\"entering into\"},{\"word\":\"visṛjāmi\",\"translation\":\"I create\"},{\"word\":\"punaḥ punaḥ\",\"translation\":\"again and again\"},{\"word\":\"bhūta-grāmam\",\"translation\":\"all the cosmic manifestations\"},{\"word\":\"imam\",\"translation\":\"these\"},{\"word\":\"kṛtsnam\",\"translation\":\"in total\"},{\"word\":\"avaśam\",\"translation\":\"automatically\"},{\"word\":\"prakṛteḥ\",\"translation\":\"of the force of nature\"},{\"word\":\"vaśāt\",\"translation\":\"under obligation\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2621,\"bb\":2323,\"url_path\":\"/en/library/bg/9/8/b2323/\",\"body_value\":\"The whole cosmic order is under Me. Under My will it is automatically manifested again and again, and under My will it is annihilated at the end.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2622,\"bb\":2324,\"url_path\":\"/en/library/bg/9/8/b2324/\",\"body_value\":\"This material world is the manifestation of the inferior energy of the Supreme Personality of Godhead. This has already been explained several times. At the creation, the material energy is let loose as the mahat-tattva, into which the Lord as His first puruṣa incarnation, Mahā-viṣṇu, enters. He lies within the Causal Ocean and breathes out innumerable universes, and into each universe the Lord again enters as Garbhodaka-śāyī Viṣṇu. Each universe is in that way created. He still further manifests Himself as Kṣīrodaka-śāyī Viṣṇu, and that Viṣṇu enters into everything – even into the minute atom. This fact is explained here. He enters into everything.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2623,\"bb\":2325,\"url_path\":\"/en/library/bg/9/8/b2325/\",\"body_value\":\"$25\"}]}],\"short_title\":\"Bg. 9.8\",\"medium_title\":\"Bhagavad-gītā As It Is 9.8\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"hr